--- a/src/cache.ts
+++ b/src/cache.ts
@@ -1,19 +1,54 @@
+import { readFileSync, writeFileSync, mkdirSync } from "fs";
+import { join } from "path";
+import { tmpdir } from "os";
+
 interface Entry {
   value: string;
   expiresAt: number;
 }

-const store = new Map<string, Entry>();
+const CACHE_DIR = join(tmpdir(), "session-cache");
+const CACHE_FILE = join(CACHE_DIR, "cache.json");
+
+let store: Map<string, Entry> | null = null;
+
+const loadStore = (): Map<string, Entry> => {
+  if (store !== null) return store;
+
+  try {
+    const data = readFileSync(CACHE_FILE, "utf-8");
+    const entries = JSON.parse(data);
+    store = new Map(entries);
+  } catch {
+    store = new Map();
+  }
+
+  return store;
+};
+
+const saveStore = (): void => {
+  if (!store) return;
+  try {
+    mkdirSync(CACHE_DIR, { recursive: true });
+    writeFileSync(CACHE_FILE, JSON.stringify([...store.entries()]));
+  } catch {
+    // Silently fail on save errors to avoid crashing the app
+  }
+};

 export const put = (key: string, value: string, ttlMs: number): void => {
-  store.set(key, { value, expiresAt: Date.now() + ttlMs });
+  const map = loadStore();
+  map.set(key, { value, expiresAt: Date.now() + ttlMs });
+  saveStore();
 };

 export const get = (key: string): string | null => {
-  const entry = store.get(key);
+  const map = loadStore();
+  const entry = map.get(key);
   if (entry === undefined) return null;
   if (entry.expiresAt < Date.now()) {
-    store.delete(key);
+    map.delete(key);
+    saveStore();
     return null;
   }
   return entry.value;
